text:
.kbd-container {
  display: flex;
  align-items: center;
  gap: 1px;

  @media (-moz-platform: macos) {
    gap: 2px;
  }

  & kbd {
    color: inherit;
    text-transform: uppercase;
    font-size: 0.75rem;
    line-height: 1;
    font-weight: bold;
    border: 1px solid color-mix(in srgb, var(--layout-border-2) 60%, transparent);
    border-radius: 3px;
    display: inline-block;
    padding: 2px 3px;

    &:first-of-type {
      margin-inline-start: 3px;
    }

    @media (-moz-platform: macos) {
      font-size: 0.8rem;
    }
  }
}
